const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.3698, 29.7604]);
  const region = houston.buffer(10000); // 10km buffer

  // For April 2024 average
  const aprilStart = '2024-04-01';
  const aprilEnd = '2024-05-01';

  // For May 18, 2024 specific day
  const may18Start = '2024-05-18';
  const may18End = '2024-05-19';

  // 2. Data Acquisition - VIIRS Nighttime Lights Monthly
  const viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .select('avg_rad');

  // Get April 2024 average (monthly composite)
  const aprilCollection = viirsCol
    .filterDate(aprilStart, aprilEnd)
    .filterBounds(region);

  // Get May 2024 image (monthly composite for May)
  const mayCollection = viirsCol
    .filterDate(may18Start, may18End)
    .filterBounds(region);

  // Check if collections have data
  const aprilSize = aprilCollection.size().getInfo();
  const maySize = mayCollection.size().getInfo();

  console.log(`April 2024 Images: ${aprilSize}, May 18, 2024 Images: ${maySize}`);

  if (aprilSize === 0 || maySize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the images (monthly composites)
  const aprilImage = aprilCollection.first();
  const mayImage = mayCollection.first();

  // 3. Processing - Check valid pixels
  const aprilCount = aprilImage
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  const mayCount = mayImage
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  console.log(`April valid pixels: ${aprilCount}, May valid pixels: ${mayCount}`);

  if (aprilCount === 0 || mayCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get average radiance
  const aprilMean = aprilImage
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  const mayMean = mayImage
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

  // 5. Validation & Final Answer
  console.log(`April avg radiance: ${aprilMean.toFixed(4)}`);
  console.log(`May 18 avg radiance: ${mayMean.toFixed(4)}`);

  if (aprilMean === null || mayMean === null || 
      isNaN(aprilMean) || isNaN(mayMean) ||
      aprilMean < 0 || mayMean < 0) {
    console.log("<answer>C3</answer>");
  } else if (mayMean < aprilMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
